def transform(grid):
    h, w = len(grid), len(grid[0])

    # Read the colored markers at grid-line intersections. In these puzzles
    # the junction spacing is the repeating tile height/width.
    def marker_lines(axis):
        n = h if axis == 0 else w
        other = w if axis == 0 else h
        signal = []
        for p in range(n):
            signal.append(sum(
                (grid[p][q] if axis == 0 else grid[q][p]) != 0
                for q in range(other)
            ))
        return signal

    def period(signal):
        n = len(signal)
        best = None
        for step in range(2, n):
            for off in range(step):
                ps = list(range(off, n, step))
                if len(ps) < 3:
                    continue
                score = sum(signal[p] for p in ps)
                if best is None or score > best[0]:
                    best = (score, step, off)
        return best[1], best[2]

    sr, orow = period(marker_lines(0))
    sc, ocol = period(marker_lines(1))
    rows = list(range(orow, h, sr))
    cols = list(range(ocol, w, sc))

    # The repeated tile fill is the most common nonzero color.
    from collections import Counter
    fill = Counter(v for row in grid for v in row if v != 0).most_common(1)[0][0]

    # Output locations correspond to equal-colored 2x2 marker blocks.
    out_h = max(1, len(rows) - 2)
    out_w = max(1, len(cols) - 1)
    out = [[fill for _ in range(out_w)] for _ in range(out_h)]

    for i in range(1, len(rows) - 1):
        for j in range(len(cols) - 1):
            a = grid[rows[i]][cols[j]]
            if a != 0 and all(
                grid[rows[r]][cols[c]] == a
                for r, c in ((i, j + 1), (i + 1, j), (i + 1, j + 1))
            ):
                oi, oj = i - 1, j
                if 0 <= oi < out_h and 0 <= oj < out_w:
                    out[oi][oj] = a
    return out
